# Grammaire portugaise, expliquée dans les autres langues d'interface.
T = {
'pronuncia': {
 'es': ('Pronunciación', "Vocales nasales: ã, õ, y toda vocal seguida de m o n al final de sílaba (mãe, pão, bom, cantar).\nlh = «ll» palatal (filho), nh = «ñ» (vinho), ç = «s» (praça), ch = «sh» (chave), j y g ante e, i = «y» sonora francesa (janela, gente).\nr inicial y rr: sonido gutural (rua, carro); r entre vocales: un golpe (caro).\nEn Brasil, t y d ante el sonido «i» suenan «ch», «y» (leite, dia) y la e final átona suena «i». En Portugal las vocales átonas se reducen mucho y la s final suena «sh».\nAcento tónico como en español; las tildes marcan excepciones y la vocal abierta (á, é, ó) o cerrada (â, ê, ô).", ['Mi hijo bebe vino.', '¡Buenos días!']),
 'de': ('Aussprache', "Nasalvokale: ã, õ und jeder Vokal vor m oder n am Silbenende (mãe, pão, bom, cantar).\nlh = weiches „lj“ (filho), nh = „nj“ (vinho), ç = „s“ (praça), ch = „sch“ (chave), j und g vor e, i = wie „j“ in „Journal“.\nr am Wortanfang und rr: rauer Laut (rua, carro); r zwischen Vokalen: ein Zungenschlag (caro).\nIn Brasilien werden t und d vor „i“-Laut zu „tsch“, „dsch“ (leite, dia), und unbetontes e am Ende klingt wie „i“. In Portugal werden unbetonte Vokale stark verkürzt, s am Ende klingt wie „sch“.\nBetonung wie im Spanischen; Akzente markieren Ausnahmen und offene (á, é, ó) oder geschlossene (â, ê, ô) Vokale.", ['Mein Sohn trinkt Wein.', 'Guten Morgen!']),
 'it': ('Pronuncia', "Vocali nasali: ã, õ e ogni vocale seguita da m o n a fine sillaba (mãe, pão, bom, cantar).\nlh = «gli» (filho), nh = «gn» (vinho), ç = «s» (praça), ch = «sc» di «scena» (chave), j e g davanti a e, i = «j» francese (janela, gente).\nr iniziale e rr: suono gutturale (rua, carro); r tra vocali: un colpo di lingua (caro).\nIn Brasile t e d davanti al suono «i» diventano «ci», «gi» (leite, dia) e la e finale atona suona «i». In Portogallo le vocali atone si riducono molto e la s finale suona «sc».\nAccento come in spagnolo; gli accenti scritti segnano le eccezioni e la vocale aperta (á, é, ó) o chiusa (â, ê, ô).", ['Mio figlio beve vino.', 'Buongiorno!']),
 'ja': ('発音', "鼻母音：ã, õ、および音節末の m, n の前の母音（mãe, pão, bom, cantar）。\nlh は「リャ」行（filho）、nh は「ニャ」行（vinho）、ç は「ス」（praça）、ch は「シャ」行（chave）、e, i の前の j, g は「ジャ」行（janela, gente）。\n語頭の r と rr は喉の音（rua, carro）、母音の間の r は舌を一回はじく音（caro）。\nブラジルでは「イ」の音の前の t, d が「チ」「ジ」（leite, dia）、アクセントのない語末の e は「イ」。ポルトガルではアクセントのない母音が弱まり、語末の s は「シュ」。\nアクセントの位置はスペイン語と同じ。記号は例外と、開いた母音（á, é, ó）・閉じた母音（â, ê, ô）を示します。", ['息子はワインを飲みます。', 'おはようございます！']),
 'zh': ('发音', "鼻化元音：ã, õ，以及音节末尾 m 或 n 前的元音（mãe, pão, bom, cantar）。\nlh 读软「ly」（filho），nh 读「ny」（vinho），ç 读「s」（praça），ch 读「sh」（chave），e, i 前的 j 和 g 读如法语的「j」（janela, gente）。\n词首 r 和 rr 读喉音（rua, carro）；元音之间的 r 舌尖弹一下（caro）。\n巴西：t、d 在「i」音前读「q」「j」（leite, dia），词尾非重读 e 读「i」。葡萄牙：非重读元音弱化，词尾 s 读「sh」。\n重音规则同西班牙语；重音符号标出例外以及开元音（á, é, ó）或闭元音（â, ê, ô）。", ['我儿子喝葡萄酒。', '早上好！']),
 'ko': ('발음', "비모음: ã, õ, 그리고 음절 끝 m이나 n 앞의 모음(mãe, pão, bom, cantar).\nlh는 부드러운 「리」(filho), nh는 「냐」(vinho), ç는 「ㅅ」(praça), ch는 「시」(chave), e, i 앞의 j, g는 「ㅈ」에 가까운 소리(janela, gente).\n단어 처음의 r과 rr은 목구멍 소리(rua, carro), 모음 사이의 r은 혀를 한 번 튕기는 소리(caro).\n브라질에서는 「이」 소리 앞의 t, d가 「치」, 「지」(leite, dia)가 되고 강세 없는 끝의 e는 「이」로 들립니다. 포르투갈에서는 강세 없는 모음이 약해지고 끝의 s는 「시」.\n강세 위치는 스페인어와 같으며, 강세 표시는 예외와 열린 모음(á, é, ó), 닫힌 모음(â, ê, ô)을 나타냅니다.", ['아들이 와인을 마셔요.', '좋은 아침이에요!']),
 'lt': ('Tarimas', "Nosiniai balsiai: ã, õ ir kiekvienas balsis prieš m ar n skiemens gale (mãe, pão, bom, cantar).\nlh = minkštas „lj“ (filho), nh = „nj“ (vinho), ç = „s“ (praça), ch = „š“ (chave), j ir g prieš e, i = „ž“ (janela, gente).\nr žodžio pradžioje ir rr: gerklinis garsas (rua, carro); r tarp balsių: vienas smūgis (caro).\nBrazilijoje t ir d prieš „i“ garsą tariami „č“, „dž“ (leite, dia), o nekirčiuotas galinis e – kaip „i“. Portugalijoje nekirčiuoti balsiai labai redukuojami, galinis s tariamas „š“.\nKirtis kaip ispanų kalboje; ženklai žymi išimtis ir atvirą (á, é, ó) ar uždarą (â, ê, ô) balsį.", ['Mano sūnus geria vyną.', 'Labas rytas!']),
 'tl': ('Pagbigkas', "Mga patinig na pailong: ã, õ, at anumang patinig bago ang m o n sa dulo ng pantig (mãe, pão, bom, cantar).\nlh = malambot na «ly» (filho), nh = «ny» (vinho), ç = «s» (praça), ch = «sh» (chave), j at g bago ang e, i = parang «zh» (janela, gente).\nr sa simula at rr: tunog-lalamunan (rua, carro); r sa pagitan ng patinig: isang pitik (caro).\nSa Brazil, ang t at d bago ang tunog «i» ay nagiging «ts», «dy» (leite, dia) at ang huling e na walang diin ay «i». Sa Portugal, humihina ang patinig na walang diin at «sh» ang huling s.\nPareho sa Espanyol ang diin; ang tuldik ay nagpapakita ng eksepsiyon at ng bukas (á, é, ó) o saradong (â, ê, ô) patinig.", ['Umiinom ng alak ang anak ko.', 'Magandang umaga!']),
},
'articles': {
 'es': ('El género, los artículos y el plural', "El masculino suele acabar en -o, el femenino en -a; excepciones: o dia, o problema, a mão. Los sustantivos en -ção, -dade, -agem son femeninos.\nArtículos definidos: o, a, os, as. Indefinidos: um, uma, uns, umas.\nPlural: + s (casa → casas); consonante + es (flor → flores); -m → -ns (homem → homens); -ão → -ões, -ães o -ãos (limão → limões, pão → pães, mão → mãos); -al → -ais (animal → animais).", ['El libro está en la mesa.', 'Tengo dos hermanos.']),
 'de': ('Genus, Artikel und Plural', "Maskulinum endet oft auf -o, Femininum auf -a; Ausnahmen: o dia, o problema, a mão. Nomen auf -ção, -dade, -agem sind feminin.\nBestimmte Artikel: o, a, os, as. Unbestimmte: um, uma, uns, umas.\nPlural: + s (casa → casas); Konsonant + es (flor → flores); -m → -ns (homem → homens); -ão → -ões, -ães oder -ãos (limão → limões, pão → pães, mão → mãos); -al → -ais (animal → animais).", ['Das Buch liegt auf dem Tisch.', 'Ich habe zwei Brüder.']),
 'it': ('Il genere, gli articoli e il plurale', "Il maschile finisce spesso in -o, il femminile in -a; eccezioni: o dia, o problema, a mão. I nomi in -ção, -dade, -agem sono femminili.\nArticoli determinativi: o, a, os, as. Indeterminativi: um, uma, uns, umas.\nPlurale: + s (casa → casas); consonante + es (flor → flores); -m → -ns (homem → homens); -ão → -ões, -ães o -ãos (limão → limões, pão → pães, mão → mãos); -al → -ais (animal → animais).", ['Il libro è sul tavolo.', 'Ho due fratelli.']),
 'ja': ('性・冠詞・複数形', "男性名詞はふつう -o、女性名詞は -a で終わります。例外：o dia, o problema, a mão。-ção, -dade, -agem で終わる名詞は女性。\n定冠詞：o, a, os, as。不定冠詞：um, uma, uns, umas。\n複数形：+ s（casa → casas）、子音 + es（flor → flores）、-m → -ns（homem → homens）、-ão → -ões, -ães, -ãos（limão → limões, pão → pães, mão → mãos）、-al → -ais（animal → animais）。", ['本はテーブルの上にあります。', '兄弟が二人います。']),
 'zh': ('性、冠词与复数', "阳性常以 -o 结尾，阴性以 -a 结尾；例外：o dia, o problema, a mão。以 -ção、-dade、-agem 结尾的名词为阴性。\n定冠词：o, a, os, as。不定冠词：um, uma, uns, umas。\n复数：+ s（casa → casas）；辅音 + es（flor → flores）；-m → -ns（homem → homens）；-ão → -ões、-ães 或 -ãos（limão → limões, pão → pães, mão → mãos）；-al → -ais（animal → animais）。", ['书在桌子上。', '我有两个兄弟。']),
 'ko': ('성, 관사, 복수형', "남성은 보통 -o, 여성은 -a로 끝납니다. 예외: o dia, o problema, a mão. -ção, -dade, -agem으로 끝나는 명사는 여성입니다.\n정관사: o, a, os, as. 부정관사: um, uma, uns, umas.\n복수형: + s(casa → casas), 자음 + es(flor → flores), -m → -ns(homem → homens), -ão → -ões, -ães, -ãos(limão → limões, pão → pães, mão → mãos), -al → -ais(animal → animais).", ['책은 탁자 위에 있어요.', '형제가 둘 있어요.']),
 'lt': ('Giminė, artikeliai ir daugiskaita', "Vyriškoji giminė dažnai baigiasi -o, moteriškoji -a; išimtys: o dia, o problema, a mão. Daiktavardžiai su -ção, -dade, -agem – moteriškosios giminės.\nŽymimieji artikeliai: o, a, os, as. Nežymimieji: um, uma, uns, umas.\nDaugiskaita: + s (casa → casas); priebalsis + es (flor → flores); -m → -ns (homem → homens); -ão → -ões, -ães arba -ãos (limão → limões, pão → pães, mão → mãos); -al → -ais (animal → animais).", ['Knyga ant stalo.', 'Turiu du brolius.']),
 'tl': ('Kasarian, pantukoy at maramihan', "Karaniwang nagtatapos sa -o ang panlalaki at sa -a ang pambabae; eksepsiyon: o dia, o problema, a mão. Pambabae ang mga nagtatapos sa -ção, -dade, -agem.\nTiyak na pantukoy: o, a, os, as. Di-tiyak: um, uma, uns, umas.\nMaramihan: + s (casa → casas); katinig + es (flor → flores); -m → -ns (homem → homens); -ão → -ões, -ães o -ãos (limão → limões, pão → pães, mão → mãos); -al → -ais (animal → animais).", ['Nasa mesa ang libro.', 'May dalawa akong kapatid na lalaki.']),
},
'ser-estar': {
 'es': ('Ser y estar', "ser: sou, és, é, somos, sois, são — identidad, origen, profesión, rasgo permanente, hora. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — lugar, estado pasajero, tiempo atmosférico. Estou cansado. Está frio.\nLugar fijo de un edificio o una ciudad: ficar o ser (Lisboa fica em Portugal), donde el español usaría estar.", ['Soy estudiante.', '¿Dónde está usted?']),
 'de': ('Ser und estar', "ser: sou, és, é, somos, sois, são — Identität, Herkunft, Beruf, dauerhafte Eigenschaft, Uhrzeit. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — Ort, vorübergehender Zustand, Wetter. Estou cansado. Está frio.\nFester Ort eines Gebäudes oder einer Stadt: ficar oder ser (Lisboa fica em Portugal).", ['Ich bin Student.', 'Wo sind Sie?']),
 'it': ('Ser e estar', "ser: sou, és, é, somos, sois, são — identità, origine, professione, caratteristica permanente, ora. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — luogo, stato passeggero, tempo atmosferico. Estou cansado. Está frio.\nPosizione fissa di un edificio o di una città: ficar o ser (Lisboa fica em Portugal).", ['Sono studente.', 'Dove si trova?']),
 'ja': ('ser と estar', "ser：sou, és, é, somos, sois, são。正体・出身・職業・変わらない性質・時刻。Sou brasileiro. São duas horas。\nestar：estou, estás, está, estamos, estais, estão。場所・一時的な状態・天気。Estou cansado. Está frio。\n建物や町の位置には ficar か ser を使います（Lisboa fica em Portugal）。", ['私は学生です。', 'どこにいますか？']),
 'zh': ('ser 与 estar', "ser：sou, és, é, somos, sois, são —— 身份、来源、职业、持久特征、时间。Sou brasileiro. São duas horas。\nestar：estou, estás, está, estamos, estais, estão —— 位置、暂时状态、天气。Estou cansado. Está frio。\n建筑物或城市的固定位置用 ficar 或 ser（Lisboa fica em Portugal）。", ['我是学生。', '您在哪儿？']),
 'ko': ('ser와 estar', "ser: sou, és, é, somos, sois, são — 정체, 출신, 직업, 변하지 않는 성질, 시각. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — 위치, 일시적인 상태, 날씨. Estou cansado. Está frio.\n건물이나 도시의 고정된 위치에는 ficar나 ser를 씁니다(Lisboa fica em Portugal).", ['저는 학생이에요.', '어디 계세요?']),
 'lt': ('Ser ir estar', "ser: sou, és, é, somos, sois, são — tapatybė, kilmė, profesija, nuolatinė savybė, laikas. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — vieta, laikina būsena, orai. Estou cansado. Está frio.\nPastato ar miesto nuolatinė vieta: ficar arba ser (Lisboa fica em Portugal).", ['Aš studentas.', 'Kur jūs esate?']),
 'tl': ('Ser at estar', "ser: sou, és, é, somos, sois, são — pagkakakilanlan, pinagmulan, trabaho, permanenteng katangian, oras. Sou brasileiro. São duas horas.\nestar: estou, estás, está, estamos, estais, estão — lugar, pansamantalang kalagayan, panahon. Estou cansado. Está frio.\nPermanenteng lugar ng gusali o lungsod: ficar o ser (Lisboa fica em Portugal).", ['Estudyante ako.', 'Nasaan po kayo?']),
},
'present': {
 'es': ('El presente', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\nEn Brasil, «você» (tú) y «a gente» (nosotros) llevan la tercera persona del singular; «tu» es corriente en Portugal.\nIrregulares: ter (tenho, tem, temos, têm), ir (vou, vai, vamos, vão), fazer (faço, faz), poder (posso, pode), querer (quero, quer), dizer (digo, diz), vir (venho, vem), saber (sei), dar (dou).", ['Hablo portugués.', 'Tengo hambre.', '¿Quiere café?']),
 'de': ('Das Präsens', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\nIn Brasilien nehmen „você“ (du) und „a gente“ (wir) die 3. Person Singular; „tu“ ist in Portugal üblich.\nUnregelmäßig: ter (tenho, tem, temos, têm), ir (vou, vai, vamos, vão), fazer (faço, faz), poder (posso, pode), querer (quero, quer), dizer (digo, diz), vir (venho, vem), saber (sei), dar (dou).", ['Ich spreche Portugiesisch.', 'Ich habe Hunger.', 'Möchten Sie Kaffee?']),
 'it': ('Il presente', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\nIn Brasile «você» (tu) e «a gente» (noi) vogliono la terza persona singolare; «tu» è comune in Portogallo.\nIrregolari: ter (tenho, tem, temos, têm), ir (vou, vai, vamos, vão), fazer (faço, faz), poder (posso, pode), querer (quero, quer), dizer (digo, diz), vir (venho, vem), saber (sei), dar (dou).", ['Parlo portoghese.', 'Ho fame.', 'Vuole un caffè?']),
 'ja': ('現在形', "falar：falo, falas, fala, falamos, falais, falam。comer：como, comes, come, comemos, comeis, comem。partir：parto, partes, parte, partimos, partis, partem。\nブラジルでは você（あなた）と a gente（私たち）に三人称単数の形を使います。ポルトガルでは tu がふつうです。\n不規則：ter（tenho, tem, temos, têm）、ir（vou, vai, vamos, vão）、fazer（faço, faz）、poder（posso, pode）、querer（quero, quer）、dizer（digo, diz）、vir（venho, vem）、saber（sei）、dar（dou）。", ['ポルトガル語を話します。', 'お腹がすいています。', 'コーヒーはいかがですか？']),
 'zh': ('现在时', "falar：falo, falas, fala, falamos, falais, falam。comer：como, comes, come, comemos, comeis, comem。partir：parto, partes, parte, partimos, partis, partem。\n在巴西，você（你）和 a gente（我们）用第三人称单数；葡萄牙常用 tu。\n不规则：ter（tenho, tem, temos, têm），ir（vou, vai, vamos, vão），fazer（faço, faz），poder（posso, pode），querer（quero, quer），dizer（digo, diz），vir（venho, vem），saber（sei），dar（dou）。", ['我说葡萄牙语。', '我饿了。', '您要咖啡吗？']),
 'ko': ('현재형', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\n브라질에서는 você(너)와 a gente(우리)에 3인칭 단수를 씁니다. 포르투갈에서는 tu가 일반적입니다.\n불규칙: ter(tenho, tem, temos, têm), ir(vou, vai, vamos, vão), fazer(faço, faz), poder(posso, pode), querer(quero, quer), dizer(digo, diz), vir(venho, vem), saber(sei), dar(dou).", ['저는 포르투갈어를 해요.', '배고파요.', '커피 드실래요?']),
 'lt': ('Esamasis laikas', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\nBrazilijoje „você“ (tu) ir „a gente“ (mes) vartojami su vienaskaitos trečiuoju asmeniu; Portugalijoje įprastas „tu“.\nNetaisyklingi: ter (tenho, tem, temos, têm), ir (vou, vai, vamos, vão), fazer (faço, faz), poder (posso, pode), querer (quero, quer), dizer (digo, diz), vir (venho, vem), saber (sei), dar (dou).", ['Kalbu portugališkai.', 'Esu alkanas.', 'Ar norite kavos?']),
 'tl': ('Ang kasalukuyan', "falar: falo, falas, fala, falamos, falais, falam. comer: como, comes, come, comemos, comeis, comem. partir: parto, partes, parte, partimos, partis, partem.\nSa Brazil, ikatlong panauhang isahan ang gamit sa «você» (ikaw) at «a gente» (kami / tayo); karaniwan ang «tu» sa Portugal.\nDi-regular: ter (tenho, tem, temos, têm), ir (vou, vai, vamos, vão), fazer (faço, faz), poder (posso, pode), querer (quero, quer), dizer (digo, diz), vir (venho, vem), saber (sei), dar (dou).", ['Nagsasalita ako ng Portuges.', 'Gutom ako.', 'Gusto mo ba ng kape?']),
},
'contractions': {
 'es': ('Las preposiciones y sus contracciones', "de + o / a = do / da; em + o / a = no / na; a + o = ao, a + a = à; por + o / a = pelo / pela. También: dum, num, neste, nesse, daquele.\nem (en), de (de), a (a), para (para, hacia), com (con), por (por).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['Vivo en Brasil.', 'Me gusta tu coche.']),
 'de': ('Präpositionen und ihre Verschmelzungen', "de + o / a = do / da; em + o / a = no / na; a + o = ao, a + a = à; por + o / a = pelo / pela. Ebenso: dum, num, neste, nesse, daquele.\nem (in), de (von, aus), a (zu, nach), para (für, nach), com (mit), por (durch, für).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['Ich wohne in Brasilien.', 'Mir gefällt dein Auto.']),
 'it': ('Le preposizioni e le loro contrazioni', "de + o / a = do / da; em + o / a = no / na; a + o = ao, a + a = à; por + o / a = pelo / pela. Anche: dum, num, neste, nesse, daquele.\nem (in), de (di, da), a (a), para (per, verso), com (con), por (per, attraverso).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['Abito in Brasile.', 'Mi piace la tua macchina.']),
 'ja': ('前置詞と縮約形', "de + o / a = do / da、em + o / a = no / na、a + o = ao、a + a = à、por + o / a = pelo / pela。ほかに dum, num, neste, nesse, daquele。\nem（〜に、〜で）、de（〜の、〜から）、a（〜へ）、para（〜のために、〜へ）、com（〜と）、por（〜によって、〜を通って）。\nVou ao cinema. Moro no Brasil. Gosto de música。", ['ブラジルに住んでいます。', 'あなたの車が気に入っています。']),
 'zh': ('介词及其缩合形式', "de + o / a = do / da；em + o / a = no / na；a + o = ao，a + a = à；por + o / a = pelo / pela。还有：dum, num, neste, nesse, daquele。\nem（在），de（……的，从），a（到），para（为了，去），com（和），por（经过，由）。\nVou ao cinema. Moro no Brasil. Gosto de música。", ['我住在巴西。', '我喜欢你的车。']),
 'ko': ('전치사와 축약형', "de + o / a = do / da, em + o / a = no / na, a + o = ao, a + a = à, por + o / a = pelo / pela. 그 밖에 dum, num, neste, nesse, daquele.\nem(~에, ~에서), de(~의, ~로부터), a(~로), para(~을 위해, ~로), com(~와 함께), por(~에 의해, ~을 통해).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['저는 브라질에 살아요.', '당신 차가 마음에 들어요.']),
 'lt': ('Prielinksniai ir jų sutraukimai', "de + o / a = do / da; em + o / a = no / na; a + o = ao, a + a = à; por + o / a = pelo / pela. Taip pat: dum, num, neste, nesse, daquele.\nem (į, -e), de (iš, -o), a (į), para (kam, į), com (su), por (per, dėl).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['Gyvenu Brazilijoje.', 'Man patinka tavo automobilis.']),
 'tl': ('Mga pang-ukol at ang pagsasama nila', "de + o / a = do / da; em + o / a = no / na; a + o = ao, a + a = à; por + o / a = pelo / pela. Gayundin: dum, num, neste, nesse, daquele.\nem (sa), de (ng, mula sa), a (sa, papunta), para (para sa, papunta), com (kasama), por (sa pamamagitan, dahil).\nVou ao cinema. Moro no Brasil. Gosto de música.", ['Nakatira ako sa Brazil.', 'Gusto ko ang kotse mo.']),
},
'negation-questions': {
 'es': ('Negación y preguntas', "Negación: «não» delante del verbo. Nunca, nada, ninguém (nadie): Não vejo nada.\nPregunta: mismo orden que la afirmación, entonación ascendente. Interrogativos: o que / que, quem, onde, quando, como, quanto, por que (por quê al final), qual.\nSe suele responder repitiendo el verbo: — Você fala inglês? — Falo.", ['¿Dónde vive usted?', 'No lo sé.']),
 'de': ('Verneinung und Fragen', "Verneinung: „não“ vor dem Verb. Nunca (nie), nada (nichts), ninguém (niemand): Não vejo nada.\nFrage: gleiche Wortstellung wie die Aussage, steigende Intonation. Fragewörter: o que / que, quem, onde, quando, como, quanto, por que (am Satzende por quê), qual.\nMan antwortet oft mit dem Verb: — Você fala inglês? — Falo.", ['Wo wohnen Sie?', 'Ich weiß es nicht.']),
 'it': ('Negazione e domande', "Negazione: «não» davanti al verbo. Nunca (mai), nada (niente), ninguém (nessuno): Não vejo nada.\nDomanda: stesso ordine dell'affermazione, intonazione ascendente. Interrogativi: o que / que, quem, onde, quando, como, quanto, por que (por quê in fondo), qual.\nSi risponde spesso ripetendo il verbo: — Você fala inglês? — Falo.", ['Dove abita?', 'Non lo so.']),
 'ja': ('否定と疑問', "否定は動詞の前に「não」。nunca（決して）、nada（何も）、ninguém（誰も）：Não vejo nada。\n疑問文は平叙文と同じ語順で、語尾を上げます。疑問詞：o que / que, quem, onde, quando, como, quanto, por que（文末では por quê）、qual。\n答えるときは動詞をくり返すことがよくあります：— Você fala inglês? — Falo。", ['どこに住んでいますか？', 'わかりません。']),
 'zh': ('否定与疑问', "否定：在动词前加「não」。nunca（从不），nada（什么也不），ninguém（没有人）：Não vejo nada。\n疑问：与陈述句语序相同，语调上扬。疑问词：o que / que, quem, onde, quando, como, quanto, por que（句末用 por quê），qual。\n常重复动词来回答：— Você fala inglês? — Falo。", ['您住在哪儿？', '我不知道。']),
 'ko': ('부정과 의문', "부정: 동사 앞에 「não」. nunca(결코), nada(아무것도), ninguém(아무도): Não vejo nada.\n의문문은 평서문과 어순이 같고 억양을 올립니다. 의문사: o que / que, quem, onde, quando, como, quanto, por que(문장 끝에서는 por quê), qual.\n대답할 때 동사를 되풀이하는 경우가 많습니다: — Você fala inglês? — Falo.", ['어디 사세요?', '몰라요.']),
 'lt': ('Neiginys ir klausimai', "Neiginys: „não“ prieš veiksmažodį. Nunca (niekada), nada (nieko), ninguém (niekas): Não vejo nada.\nKlausimas: tokia pati tvarka kaip teiginyje, kylanti intonacija. Klausiamieji žodžiai: o que / que, quem, onde, quando, como, quanto, por que (gale por quê), qual.\nDažnai atsakoma pakartojant veiksmažodį: — Você fala inglês? — Falo.", ['Kur jūs gyvenate?', 'Nežinau.']),
 'tl': ('Negatibo at tanong', "Negatibo: «não» bago ang pandiwa. Nunca (hindi kailanman), nada (wala), ninguém (walang sinuman): Não vejo nada.\nTanong: parehong ayos ng paturol, pataas na tono. Pananong: o que / que, quem, onde, quando, como, quanto, por que (por quê sa dulo), qual.\nMadalas sumagot sa pag-ulit ng pandiwa: — Você fala inglês? — Falo.", ['Saan po kayo nakatira?', 'Hindi ko alam.']),
},
'possessifs': {
 'es': ('Posesivos y demostrativos', "meu / minha, teu / tua, seu / sua, nosso / nossa (+ s en plural). En Portugal va precedido de artículo (o meu livro); en Brasil es opcional. Como «seu» es ambiguo, se dice a menudo dele, dela, deles: o carro dele.\nDemostrativos: este / esta (aquí), esse / essa (cerca de ti), aquele / aquela (allí); neutros: isto, isso, aquilo.", ['Este es mi amigo.', '¿Qué es eso?']),
 'de': ('Possessiv- und Demonstrativbegleiter', "meu / minha, teu / tua, seu / sua, nosso / nossa (+ s im Plural). In Portugal steht der Artikel davor (o meu livro); in Brasilien ist er freiwillig. Weil „seu“ mehrdeutig ist, sagt man oft dele, dela, deles: o carro dele.\nDemonstrativ: este / esta (hier), esse / essa (bei dir), aquele / aquela (dort); Neutrum: isto, isso, aquilo.", ['Das ist mein Freund.', 'Was ist das?']),
 'it': ('Possessivi e dimostrativi', "meu / minha, teu / tua, seu / sua, nosso / nossa (+ s al plurale). In Portogallo c'è l'articolo (o meu livro); in Brasile è facoltativo. Poiché «seu» è ambiguo, si dice spesso dele, dela, deles: o carro dele.\nDimostrativi: este / esta (qui), esse / essa (vicino a te), aquele / aquela (là); neutri: isto, isso, aquilo.", ['Questo è il mio amico.', "Che cos'è?"]),
 'ja': ('所有詞と指示詞', "meu / minha, teu / tua, seu / sua, nosso / nossa（複数は + s）。ポルトガルでは冠詞をつけます（o meu livro）。ブラジルではつけてもつけなくてもかまいません。seu はあいまいなので、dele, dela, deles もよく使います：o carro dele。\n指示詞：este / esta（これ）、esse / essa（それ）、aquele / aquela（あれ）。中性：isto, isso, aquilo。", ['こちらは私の友達です。', 'それは何ですか？']),
 'zh': ('物主词与指示词', "meu / minha, teu / tua, seu / sua, nosso / nossa（复数加 s）。在葡萄牙前面加冠词（o meu livro）；在巴西可加可不加。由于 seu 有歧义，常说 dele, dela, deles：o carro dele。\n指示词：este / esta（这，近处），esse / essa（那，在你旁边），aquele / aquela（那，远处）；中性：isto, isso, aquilo。", ['这是我的朋友。', '那是什么？']),
 'ko': ('소유사와 지시사', "meu / minha, teu / tua, seu / sua, nosso / nossa(복수는 + s). 포르투갈에서는 관사를 붙이고(o meu livro), 브라질에서는 붙여도 되고 안 붙여도 됩니다. seu는 뜻이 모호해서 dele, dela, deles를 자주 씁니다: o carro dele.\n지시사: este / esta(이것), esse / essa(그것), aquele / aquela(저것). 중성: isto, isso, aquilo.", ['이쪽은 제 친구예요.', '그게 뭐예요?']),
 'lt': ('Savybiniai ir parodomieji žodžiai', "meu / minha, teu / tua, seu / sua, nosso / nossa (+ s daugiskaitoje). Portugalijoje prieš juos artikelis (o meu livro); Brazilijoje nebūtinas. Kadangi „seu“ dviprasmis, dažnai sakoma dele, dela, deles: o carro dele.\nParodomieji: este / esta (čia), esse / essa (prie tavęs), aquele / aquela (ten); bevardės giminės: isto, isso, aquilo.", ['Tai mano draugas.', 'Kas tai?']),
 'tl': ('Paari at pamatlig', "meu / minha, teu / tua, seu / sua, nosso / nossa (+ s sa maramihan). Sa Portugal, nauuna ang pantukoy (o meu livro); sa Brazil, hindi sapilitan. Dahil malabo ang «seu», madalas sinasabing dele, dela, deles: o carro dele.\nPamatlig: este / esta (ito), esse / essa (iyan), aquele / aquela (iyon); walang kasarian: isto, isso, aquilo.", ['Ito ang kaibigan ko.', 'Ano iyan?']),
},
'progressif-futur': {
 'es': ('Acción en curso y futuro próximo', "En curso: estar + gerundio en Brasil (Estou trabalhando), estar a + infinitivo en Portugal (Estou a trabalhar).\nFuturo próximo: ir + infinitivo, sin preposición. Vou viajar amanhã. Es el futuro habitual al hablar.\nPasado reciente: acabar de + infinitivo.", ['¿Qué estás haciendo?', 'Voy a comprar pan.']),
 'de': ('Laufende Handlung und nahe Zukunft', "Laufend: estar + Gerundium in Brasilien (Estou trabalhando), estar a + Infinitiv in Portugal (Estou a trabalhar).\nNahe Zukunft: ir + Infinitiv, ohne Präposition. Vou viajar amanhã. Das ist die übliche gesprochene Zukunft.\nGerade Geschehenes: acabar de + Infinitiv.", ['Was machst du gerade?', 'Ich kaufe gleich Brot.']),
 'it': ('Azione in corso e futuro prossimo', "In corso: estar + gerundio in Brasile (Estou trabalhando), estar a + infinito in Portogallo (Estou a trabalhar).\nFuturo prossimo: ir + infinito, senza preposizione. Vou viajar amanhã. È il futuro normale nel parlato.\nPassato recente: acabar de + infinito.", ['Che cosa stai facendo?', 'Vado a comprare il pane.']),
 'ja': ('進行中の動作と近い未来', "進行中：ブラジルでは estar + 現在分詞（Estou trabalhando）、ポルトガルでは estar a + 不定詞（Estou a trabalhar）。\n近い未来：ir + 不定詞（前置詞なし）。Vou viajar amanhã。話し言葉ではこれがふつうの未来です。\n直前の過去：acabar de + 不定詞。", ['何をしているの？', 'パンを買いに行きます。']),
 'zh': ('正在进行与近将来', "正在进行：巴西用 estar + 副动词（Estou trabalhando），葡萄牙用 estar a + 不定式（Estou a trabalhar）。\n近将来：ir + 不定式，不加介词。Vou viajar amanhã。这是口语中最常用的将来时。\n刚刚完成：acabar de + 不定式。", ['你在做什么？', '我要去买面包。']),
 'ko': ('진행 중인 동작과 가까운 미래', "진행: 브라질에서는 estar + 현재분사(Estou trabalhando), 포르투갈에서는 estar a + 동사원형(Estou a trabalhar).\n가까운 미래: ir + 동사원형(전치사 없음). Vou viajar amanhã. 말할 때 쓰는 일반적인 미래입니다.\n방금 한 일: acabar de + 동사원형.", ['뭐 하고 있어?', '빵 사러 갈 거예요.']),
 'lt': ('Vykstantis veiksmas ir artimasis būsimasis', "Vykstantis: Brazilijoje estar + padalyvis (Estou trabalhando), Portugalijoje estar a + bendratis (Estou a trabalhar).\nArtimasis būsimasis: ir + bendratis, be prielinksnio. Vou viajar amanhã. Tai įprastas šnekamosios kalbos būsimasis.\nKą tik įvykęs: acabar de + bendratis.", ['Ką tu darai?', 'Eisiu nusipirkti duonos.']),
 'tl': ('Kilos na nangyayari at malapit na hinaharap', "Nangyayari: estar + gerundio sa Brazil (Estou trabalhando), estar a + infinitive sa Portugal (Estou a trabalhar).\nMalapit na hinaharap: ir + infinitive, walang pang-ukol. Vou viajar amanhã. Ito ang karaniwang hinaharap sa usapan.\nKatatapos lang: acabar de + infinitive.", ['Ano ang ginagawa mo?', 'Bibili ako ng tinapay.']),
},
'preterito': {
 'es': ('El pretérito perfecto simple', "Es el pasado corriente, oral y escrito (equivale al indefinido español).\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\nIrregulares: ser / ir (fui, foi, fomos, foram), ter (tive, teve), estar (estive, esteve), fazer (fiz, fez), dizer (disse), poder (pude, pôde), vir (vim, veio), ver (vi, viu), dar (dei, deu).", ['Ayer fui a la playa.', 'Él dijo la verdad.']),
 'de': ('Das einfache Perfekt (pretérito perfeito)', "Die gewöhnliche Vergangenheit, mündlich wie schriftlich.\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\nUnregelmäßig: ser / ir (fui, foi, fomos, foram), ter (tive, teve), estar (estive, esteve), fazer (fiz, fez), dizer (disse), poder (pude, pôde), vir (vim, veio), ver (vi, viu), dar (dei, deu).", ['Gestern war ich am Strand.', 'Er hat die Wahrheit gesagt.']),
 'it': ('Il passato semplice (pretérito perfeito)', "È il passato normale, orale e scritto (corrisponde al passato prossimo italiano).\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\nIrregolari: ser / ir (fui, foi, fomos, foram), ter (tive, teve), estar (estive, esteve), fazer (fiz, fez), dizer (disse), poder (pude, pôde), vir (vim, veio), ver (vi, viu), dar (dei, deu).", ['Ieri sono andato in spiaggia.', 'Ha detto la verità.']),
 'ja': ('完全過去', "話し言葉でも書き言葉でもふつうに使う過去形です。\nfalar：falei, falaste, falou, falamos, falastes, falaram。comer：comi, comeste, comeu, comemos, comestes, comeram。partir：parti, partiste, partiu, partimos, partistes, partiram。\n不規則：ser / ir（fui, foi, fomos, foram）、ter（tive, teve）、estar（estive, esteve）、fazer（fiz, fez）、dizer（disse）、poder（pude, pôde）、vir（vim, veio）、ver（vi, viu）、dar（dei, deu）。", ['昨日ビーチに行きました。', '彼は本当のことを言いました。']),
 'zh': ('简单过去时', "这是口语和书面语中最常用的过去时。\nfalar：falei, falaste, falou, falamos, falastes, falaram。comer：comi, comeste, comeu, comemos, comestes, comeram。partir：parti, partiste, partiu, partimos, partistes, partiram。\n不规则：ser / ir（fui, foi, fomos, foram），ter（tive, teve），estar（estive, esteve），fazer（fiz, fez），dizer（disse），poder（pude, pôde），vir（vim, veio），ver（vi, viu），dar（dei, deu）。", ['昨天我去了海滩。', '他说了实话。']),
 'ko': ('완료 과거', "말할 때도 글을 쓸 때도 흔히 쓰는 과거형입니다.\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\n불규칙: ser / ir(fui, foi, fomos, foram), ter(tive, teve), estar(estive, esteve), fazer(fiz, fez), dizer(disse), poder(pude, pôde), vir(vim, veio), ver(vi, viu), dar(dei, deu).", ['어제 해변에 갔어요.', '그는 진실을 말했어요.']),
 'lt': ('Būtasis kartinis laikas', "Įprastas būtasis laikas šnekamojoje ir rašytinėje kalboje.\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\nNetaisyklingi: ser / ir (fui, foi, fomos, foram), ter (tive, teve), estar (estive, esteve), fazer (fiz, fez), dizer (disse), poder (pude, pôde), vir (vim, veio), ver (vi, viu), dar (dei, deu).", ['Vakar buvau paplūdimyje.', 'Jis pasakė tiesą.']),
 'tl': ('Ang pretérito perfeito', "Ito ang karaniwang nakaraan, sa usapan man o sa sulat.\nfalar: falei, falaste, falou, falamos, falastes, falaram. comer: comi, comeste, comeu, comemos, comestes, comeram. partir: parti, partiste, partiu, partimos, partistes, partiram.\nDi-regular: ser / ir (fui, foi, fomos, foram), ter (tive, teve), estar (estive, esteve), fazer (fiz, fez), dizer (disse), poder (pude, pôde), vir (vim, veio), ver (vi, viu), dar (dei, deu).", ['Pumunta ako sa dalampasigan kahapon.', 'Nagsabi siya ng totoo.']),
},
'imperfeito': {
 'es': ('El imperfecto', "falava, falavas, falava, falávamos, faláveis, falavam; comia; partia. Cuatro irregulares: ser (era), ter (tinha), vir (vinha), pôr (punha).\nHábito, descripción, acción en curso en el pasado: Quando era criança, morava no Porto. También sirve de condicional familiar: Eu queria um café.", ['Cuando era niño, vivía en Lisboa.', 'Estaba lloviendo.']),
 'de': ('Das Imperfekt', "falava, falavas, falava, falávamos, faláveis, falavam; comia; partia. Vier unregelmäßige: ser (era), ter (tinha), vir (vinha), pôr (punha).\nGewohnheit, Beschreibung, laufende Handlung in der Vergangenheit: Quando era criança, morava no Porto. Umgangssprachlich auch als Konditional: Eu queria um café.", ['Als Kind habe ich in Lissabon gewohnt.', 'Es regnete.']),
 'it': ("L'imperfetto", "falava, falavas, falava, falávamos, faláveis, falavam; comia; partia. Quattro irregolari: ser (era), ter (tinha), vir (vinha), pôr (punha).\nAbitudine, descrizione, azione in corso nel passato: Quando era criança, morava no Porto. Serve anche da condizionale familiare: Eu queria um café.", ['Da bambino abitavo a Lisbona.', 'Stava piovendo.']),
 'ja': ('不完全過去', "falava, falavas, falava, falávamos, faláveis, falavam、comia、partia。不規則は四つ：ser（era）、ter（tinha）、vir（vinha）、pôr（punha）。\n過去の習慣・描写・進行中の動作：Quando era criança, morava no Porto。くだけた条件法としても使います：Eu queria um café。", ['子供のころリスボンに住んでいました。', '雨が降っていました。']),
 'zh': ('未完成过去时', "falava, falavas, falava, falávamos, faláveis, falavam；comia；partia。四个不规则：ser（era），ter（tinha），vir（vinha），pôr（punha）。\n表示过去的习惯、描写和进行中的动作：Quando era criança, morava no Porto。口语中也当条件式用：Eu queria um café。", ['我小时候住在里斯本。', '那时在下雨。']),
 'ko': ('불완료 과거', "falava, falavas, falava, falávamos, faláveis, falavam, comia, partia. 불규칙은 넷: ser(era), ter(tinha), vir(vinha), pôr(punha).\n과거의 습관, 묘사, 진행 중인 동작: Quando era criança, morava no Porto. 구어에서는 조건법처럼도 씁니다: Eu queria um café.", ['어렸을 때 리스본에 살았어요.', '비가 오고 있었어요.']),
 'lt': ('Būtasis dažninis (imperfeito)', "falava, falavas, falava, falávamos, faláveis, falavam; comia; partia. Keturi netaisyklingi: ser (era), ter (tinha), vir (vinha), pôr (punha).\nĮprotis, aprašymas, vykstantis veiksmas praeityje: Quando era criança, morava no Porto. Šnekamojoje kalboje ir kaip tariamoji: Eu queria um café.", ['Vaikystėje gyvenau Lisabonoje.', 'Lijo.']),
 'tl': ('Ang imperfeito', "falava, falavas, falava, falávamos, faláveis, falavam; comia; partia. Apat na di-regular: ser (era), ter (tinha), vir (vinha), pôr (punha).\nGawi, paglalarawan, kilos na nangyayari sa nakaraan: Quando era criança, morava no Porto. Ginagamit din bilang kondisyonal sa usapan: Eu queria um café.", ['Noong bata ako, nakatira ako sa Lisbon.', 'Umuulan noon.']),
},
'pronoms': {
 'es': ('Los pronombres complemento', "Directos: me, te, o / a, nos, os / as. Indirectos: me, te, lhe, nos, lhes.\nEn Portugal el pronombre va detrás del verbo con guion (Vejo-o. Chamo-me Ana), salvo tras não, que, un interrogativo… En Brasil va delante (Me chamo Ana) y al hablar se usa ele / ela en lugar de o / a (Eu vi ele).\nTras un infinitivo: -lo, -la (vê-lo, comprá-la).", ['Te quiero.', 'No me acuerdo.']),
 'de': ('Objektpronomen', "Direkt: me, te, o / a, nos, os / as. Indirekt: me, te, lhe, nos, lhes.\nIn Portugal folgt das Pronomen dem Verb mit Bindestrich (Vejo-o. Chamo-me Ana), außer nach não, que, Fragewörtern… In Brasilien steht es davor (Me chamo Ana), und mündlich sagt man ele / ela statt o / a (Eu vi ele).\nNach Infinitiv: -lo, -la (vê-lo, comprá-la).", ['Ich liebe dich.', 'Ich erinnere mich nicht.']),
 'it': ('I pronomi complemento', "Diretti: me, te, o / a, nos, os / as. Indiretti: me, te, lhe, nos, lhes.\nIn Portogallo il pronome segue il verbo con il trattino (Vejo-o. Chamo-me Ana), tranne dopo não, que, un interrogativo… In Brasile precede il verbo (Me chamo Ana) e nel parlato si usa ele / ela al posto di o / a (Eu vi ele).\nDopo un infinito: -lo, -la (vê-lo, comprá-la).", ['Ti amo.', 'Non mi ricordo.']),
 'ja': ('目的格代名詞', "直接目的語：me, te, o / a, nos, os / as。間接目的語：me, te, lhe, nos, lhes。\nポルトガルでは代名詞を動詞の後ろにハイフンでつけます（Vejo-o. Chamo-me Ana）。não, que, 疑問詞などの後では前に置きます。ブラジルでは動詞の前に置き（Me chamo Ana）、話し言葉では o / a の代わりに ele / ela を使います（Eu vi ele）。\n不定詞の後：-lo, -la（vê-lo, comprá-la）。", ['愛してる。', '覚えていません。']),
 'zh': ('宾格代词', "直接宾语：me, te, o / a, nos, os / as。间接宾语：me, te, lhe, nos, lhes。\n在葡萄牙，代词用连字符放在动词后（Vejo-o. Chamo-me Ana），但在 não、que、疑问词等之后放在前面。在巴西放在动词前（Me chamo Ana），口语中常用 ele / ela 代替 o / a（Eu vi ele）。\n不定式后：-lo, -la（vê-lo, comprá-la）。", ['我爱你。', '我不记得了。']),
 'ko': ('목적격 대명사', "직접 목적어: me, te, o / a, nos, os / as. 간접 목적어: me, te, lhe, nos, lhes.\n포르투갈에서는 대명사를 동사 뒤에 하이픈으로 붙이고(Vejo-o. Chamo-me Ana), não, que, 의문사 등의 뒤에서는 앞에 둡니다. 브라질에서는 동사 앞에 두며(Me chamo Ana), 말할 때는 o / a 대신 ele / ela를 씁니다(Eu vi ele).\n동사원형 뒤: -lo, -la(vê-lo, comprá-la).", ['사랑해.', '기억이 안 나요.']),
 'lt': ('Papildinio įvardžiai', "Tiesioginiai: me, te, o / a, nos, os / as. Netiesioginiai: me, te, lhe, nos, lhes.\nPortugalijoje įvardis eina po veiksmažodžio su brūkšneliu (Vejo-o. Chamo-me Ana), išskyrus po não, que, klausiamųjų žodžių… Brazilijoje jis eina prieš (Me chamo Ana), o šnekant vietoj o / a sakoma ele / ela (Eu vi ele).\nPo bendraties: -lo, -la (vê-lo, comprá-la).", ['Aš tave myliu.', 'Neprisimenu.']),
 'tl': ('Mga panghalip na layon', "Tuwiran: me, te, o / a, nos, os / as. Di-tuwiran: me, te, lhe, nos, lhes.\nSa Portugal, sumusunod sa pandiwa na may gitling (Vejo-o. Chamo-me Ana), maliban pagkatapos ng não, que, pananong… Sa Brazil, nauuna (Me chamo Ana) at sa usapan ay ele / ela ang gamit sa halip na o / a (Eu vi ele).\nPagkatapos ng infinitive: -lo, -la (vê-lo, comprá-la).", ['Mahal kita.', 'Hindi ko maalala.']),
},
'comparaison': {
 'es': ('Comparativo y superlativo', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. Irregulares: melhor, pior, maior, menor.\nSuperlativo: o mais alto da turma; -íssimo (caríssimo).\nMuito (muy, mucho), pouco, demais (demasiado), bastante.", ['Ella es más alta que yo.', 'Este es el mejor restaurante.']),
 'de': ('Komparativ und Superlativ', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. Unregelmäßig: melhor, pior, maior, menor.\nSuperlativ: o mais alto da turma; -íssimo (caríssimo).\nMuito (sehr, viel), pouco, demais (zu viel), bastante.", ['Sie ist größer als ich.', 'Das ist das beste Restaurant.']),
 'it': ('Comparativo e superlativo', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. Irregolari: melhor, pior, maior, menor.\nSuperlativo: o mais alto da turma; -íssimo (caríssimo).\nMuito (molto), pouco, demais (troppo), bastante.", ['Lei è più alta di me.', 'Questo è il miglior ristorante.']),
 'ja': ('比較級と最上級', "mais … (do) que、menos … (do) que、tão … como / quanto、tanto(s) … como。不規則：melhor, pior, maior, menor。\n最上級：o mais alto da turma、-íssimo（caríssimo）。\nmuito（とても、たくさん）、pouco、demais（〜すぎる）、bastante。", ['彼女は私より背が高いです。', 'ここが一番いいレストランです。']),
 'zh': ('比较级和最高级', "mais … (do) que，menos … (do) que，tão … como / quanto，tanto(s) … como。不规则：melhor, pior, maior, menor。\n最高级：o mais alto da turma；-íssimo（caríssimo）。\nmuito（很、很多），pouco，demais（太），bastante。", ['她比我高。', '这是最好的餐厅。']),
 'ko': ('비교급과 최상급', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. 불규칙: melhor, pior, maior, menor.\n최상급: o mais alto da turma, -íssimo(caríssimo).\nmuito(매우, 많이), pouco, demais(너무), bastante.", ['그녀는 저보다 키가 커요.', '여기가 제일 좋은 식당이에요.']),
 'lt': ('Aukštesnysis ir aukščiausiasis laipsnis', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. Netaisyklingi: melhor, pior, maior, menor.\nAukščiausiasis: o mais alto da turma; -íssimo (caríssimo).\nMuito (labai, daug), pouco, demais (per daug), bastante.", ['Ji aukštesnė už mane.', 'Tai geriausias restoranas.']),
 'tl': ('Paghahambing', "mais … (do) que, menos … (do) que, tão … como / quanto, tanto(s) … como. Di-regular: melhor, pior, maior, menor.\nPinakamataas: o mais alto da turma; -íssimo (caríssimo).\nMuito (napaka-, marami), pouco, demais (sobra), bastante.", ['Mas matangkad siya sa akin.', 'Ito ang pinakamagandang restawran.']),
},
'perfeito-composto': {
 'es': ('Ter + participio', "El «pretérito perfeito composto» (tenho falado) no es un pretérito perfecto español: expresa una acción repetida o que dura hasta ahora. Tenho trabalhado muito = últimamente trabajo mucho.\nPluscuamperfecto: tinha + participio (Eu já tinha saído).\nParticipios: -ado, -ido; irregulares: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['Últimamente estudio mucho.', 'Él ya había salido.']),
 'de': ('Ter + Partizip', "Das „pretérito perfeito composto“ (tenho falado) ist kein gewöhnliches Perfekt: Es drückt eine wiederholte oder bis jetzt andauernde Handlung aus. Tenho trabalhado muito = ich arbeite in letzter Zeit viel.\nPlusquamperfekt: tinha + Partizip (Eu já tinha saído).\nPartizipien: -ado, -ido; unregelmäßig: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['Ich lerne in letzter Zeit viel.', 'Er war schon gegangen.']),
 'it': ('Ter + participio', "Il «pretérito perfeito composto» (tenho falado) non è un passato prossimo: esprime un'azione ripetuta o che dura fino a ora. Tenho trabalhado muito = ultimamente lavoro molto.\nTrapassato: tinha + participio (Eu já tinha saído).\nParticipi: -ado, -ido; irregolari: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['Ultimamente studio molto.', 'Era già uscito.']),
 'ja': ('ter + 過去分詞', "「pretérito perfeito composto」（tenho falado）は単なる過去ではなく、今まで繰り返されている・続いている動作を表します。Tenho trabalhado muito = 最近よく働いている。\n大過去：tinha + 過去分詞（Eu já tinha saído）。\n過去分詞：-ado, -ido。不規則：feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto。", ['最近よく勉強しています。', '彼はもう出かけていました。']),
 'zh': ('ter + 过去分词', "「复合完成时」（tenho falado）不是普通的过去时：它表示反复发生或持续到现在的动作。Tenho trabalhado muito = 最近我工作很多。\n过去完成时：tinha + 过去分词（Eu já tinha saído）。\n过去分词：-ado, -ido；不规则：feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto。", ['最近我学习很多。', '他已经出去了。']),
 'ko': ('ter + 과거분사', "「pretérito perfeito composto」(tenho falado)는 단순한 과거가 아니라 지금까지 반복되거나 계속되는 동작을 나타냅니다. Tenho trabalhado muito = 요즘 일을 많이 하고 있다.\n대과거: tinha + 과거분사(Eu já tinha saído).\n과거분사: -ado, -ido. 불규칙: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['요즘 공부를 많이 해요.', '그는 이미 나가 있었어요.']),
 'lt': ('Ter + dalyvis', "„Pretérito perfeito composto“ (tenho falado) nėra paprastas būtasis: jis reiškia pasikartojantį arba iki dabar tebesitęsiantį veiksmą. Tenho trabalhado muito = pastaruoju metu daug dirbu.\nBūtasis atliktinis: tinha + dalyvis (Eu já tinha saído).\nDalyviai: -ado, -ido; netaisyklingi: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['Pastaruoju metu daug mokausi.', 'Jis jau buvo išėjęs.']),
 'tl': ('Ter + participle', "Hindi karaniwang nakaraan ang «pretérito perfeito composto» (tenho falado): kilos itong paulit-ulit o nagpapatuloy hanggang ngayon. Tenho trabalhado muito = madalas akong nagtatrabaho nitong mga nakaraan.\nPluperfect: tinha + participle (Eu já tinha saído).\nParticiple: -ado, -ido; di-regular: feito, dito, visto, escrito, posto, vindo, aberto, ganho, pago, gasto.", ['Marami akong pinag-aaralan nitong mga nakaraan.', 'Nakaalis na siya noon.']),
},
'futur-conditionnel': {
 'es': ('El futuro y el condicional', "Futuro: infinitivo + ei, ás, á, emos, eis, ão (falarei). Condicional: infinitivo + ia, ias, ia, íamos, íeis, iam (falaria). Tres raíces irregulares: dir- (dizer), far- (fazer), trar- (trazer).\nAl hablar se prefiere ir + infinitivo para el futuro y el imperfecto para el condicional.\nCortesía: Gostaria de… Poderia…?", ['Quisiera un café.', 'Mañana será otro día.']),
 'de': ('Futur und Konditional', "Futur: Infinitiv + ei, ás, á, emos, eis, ão (falarei). Konditional: Infinitiv + ia, ias, ia, íamos, íeis, iam (falaria). Drei unregelmäßige Stämme: dir- (dizer), far- (fazer), trar- (trazer).\nMündlich bevorzugt man ir + Infinitiv für die Zukunft und das Imperfekt für das Konditional.\nHöflichkeit: Gostaria de… Poderia…?", ['Ich hätte gern einen Kaffee.', 'Morgen ist ein neuer Tag.']),
 'it': ('Il futuro e il condizionale', "Futuro: infinito + ei, ás, á, emos, eis, ão (falarei). Condizionale: infinito + ia, ias, ia, íamos, íeis, iam (falaria). Tre radicali irregolari: dir- (dizer), far- (fazer), trar- (trazer).\nNel parlato si preferisce ir + infinito per il futuro e l'imperfetto per il condizionale.\nCortesia: Gostaria de… Poderia…?", ['Vorrei un caffè.', 'Domani sarà un altro giorno.']),
 'ja': ('未来形と過去未来（条件法）', "未来形：不定詞 + ei, ás, á, emos, eis, ão（falarei）。過去未来：不定詞 + ia, ias, ia, íamos, íeis, iam（falaria）。不規則な語幹は三つ：dir-（dizer）、far-（fazer）、trar-（trazer）。\n話し言葉では、未来には ir + 不定詞、条件法には不完全過去を使うことが多いです。\n丁寧な表現：Gostaria de… Poderia…?", ['コーヒーをいただきたいのですが。', '明日は明日の風が吹く。']),
 'zh': ('将来时与条件式', "将来时：不定式 + ei, ás, á, emos, eis, ão（falarei）。条件式：不定式 + ia, ias, ia, íamos, íeis, iam（falaria）。三个不规则词根：dir-（dizer），far-（fazer），trar-（trazer）。\n口语中将来时多用 ir + 不定式，条件式多用未完成过去时。\n礼貌：Gostaria de… Poderia…?", ['我想要一杯咖啡。', '明天又是新的一天。']),
 'ko': ('미래형과 조건법', "미래형: 동사원형 + ei, ás, á, emos, eis, ão(falarei). 조건법: 동사원형 + ia, ias, ia, íamos, íeis, iam(falaria). 불규칙 어간 셋: dir-(dizer), far-(fazer), trar-(trazer).\n말할 때는 미래에 ir + 동사원형, 조건법에 불완료 과거를 더 자주 씁니다.\n공손: Gostaria de… Poderia…?", ['커피 한 잔 주시겠어요?', '내일은 또 다른 날이에요.']),
 'lt': ('Būsimasis laikas ir tariamoji nuosaka', "Būsimasis: bendratis + ei, ás, á, emos, eis, ão (falarei). Tariamoji: bendratis + ia, ias, ia, íamos, íeis, iam (falaria). Trys netaisyklingi kamienai: dir- (dizer), far- (fazer), trar- (trazer).\nŠnekant būsimajam dažniau vartojama ir + bendratis, o tariamajai – imperfeito.\nMandagumas: Gostaria de… Poderia…?", ['Norėčiau kavos.', 'Rytoj bus kita diena.']),
 'tl': ('Hinaharap at kondisyonal', "Hinaharap: infinitive + ei, ás, á, emos, eis, ão (falarei). Kondisyonal: infinitive + ia, ias, ia, íamos, íeis, iam (falaria). Tatlong di-regular na ugat: dir- (dizer), far- (fazer), trar- (trazer).\nSa usapan, mas gusto ang ir + infinitive sa hinaharap at ang imperfeito sa kondisyonal.\nPaggalang: Gostaria de… Poderia…?", ['Gusto ko po ng kape.', 'Iba na ang bukas.']),
},
'imperatif': {
 'es': ('El imperativo', "Você / vocês (y la negación): formas del subjuntivo — fale, coma, parta; falem. Irregulares: seja, esteja, vá, dê, diga, faça, tenha, venha.\nTu afirmativo: tercera persona del presente (fala, come). En Brasil esta forma se usa mucho incluso con você: Fala! Vem cá!\nNegación: não + subjuntivo (Não fale. Não te preocupes).", ['¡Venga aquí!', 'No se preocupe.']),
 'de': ('Der Imperativ', "Você / vocês (und die Verneinung): Formen des Konjunktivs — fale, coma, parta; falem. Unregelmäßig: seja, esteja, vá, dê, diga, faça, tenha, venha.\nBejahtes tu: 3. Person Präsens (fala, come). In Brasilien ist diese Form auch mit você üblich: Fala! Vem cá!\nVerneinung: não + Konjunktiv (Não fale. Não te preocupes).", ['Kommen Sie her!', 'Machen Sie sich keine Sorgen.']),
 'it': ("L'imperativo", "Você / vocês (e la negazione): forme del congiuntivo — fale, coma, parta; falem. Irregolari: seja, esteja, vá, dê, diga, faça, tenha, venha.\nTu affermativo: terza persona del presente (fala, come). In Brasile questa forma si usa molto anche con você: Fala! Vem cá!\nNegazione: não + congiuntivo (Não fale. Não te preocupes).", ['Venga qui!', 'Non si preoccupi.']),
 'ja': ('命令形', "você / vocês（と否定命令）は接続法の形：fale, coma, parta、falem。不規則：seja, esteja, vá, dê, diga, faça, tenha, venha。\ntu の肯定命令は直説法現在の三人称単数（fala, come）。ブラジルでは você に対してもよく使います：Fala! Vem cá!\n否定：não + 接続法（Não fale. Não te preocupes）。", ['こちらに来てください！', '心配しないでください。']),
 'zh': ('命令式', "você / vocês（以及否定命令）用虚拟式：fale, coma, parta；falem。不规则：seja, esteja, vá, dê, diga, faça, tenha, venha。\ntu 的肯定命令 = 陈述式现在时第三人称单数（fala, come）。在巴西，对 você 也常用这种形式：Fala! Vem cá!\n否定：não + 虚拟式（Não fale. Não te preocupes）。", ['请过来！', '别担心。']),
 'ko': ('명령형', "você / vocês(와 부정 명령)는 접속법 형태: fale, coma, parta, falem. 불규칙: seja, esteja, vá, dê, diga, faça, tenha, venha.\ntu의 긍정 명령은 직설법 현재 3인칭 단수(fala, come). 브라질에서는 você에게도 자주 씁니다: Fala! Vem cá!\n부정: não + 접속법(Não fale. Não te preocupes).", ['이리 오세요!', '걱정하지 마세요.']),
 'lt': ('Liepiamoji nuosaka', "Você / vocês (ir neiginiai): konjunktyvo formos — fale, coma, parta; falem. Netaisyklingi: seja, esteja, vá, dê, diga, faça, tenha, venha.\nTeigiamas tu: esamojo laiko trečiasis asmuo (fala, come). Brazilijoje ši forma dažna net su você: Fala! Vem cá!\nNeiginys: não + konjunktyvas (Não fale. Não te preocupes).", ['Ateikite čia!', 'Nesijaudinkite.']),
 'tl': ('Ang pautos', "Você / vocês (at negatibo): anyo ng subjuntivo — fale, coma, parta; falem. Di-regular: seja, esteja, vá, dê, diga, faça, tenha, venha.\nApirmatibong tu: ikatlong panauhan ng kasalukuyan (fala, come). Sa Brazil, madalas ito kahit sa você: Fala! Vem cá!\nNegatibo: não + subjuntivo (Não fale. Não te preocupes).", ['Halika po rito!', 'Huwag po kayong mag-alala.']),
},
'subjonctif': {
 'es': ('El presente de subjuntivo', "Se forma sobre la primera persona del presente cambiando la vocal: falar → fale, fales, fale, falemos, faleis, falem; comer → coma; ter → tenha; fazer → faça; dizer → diga. Irregulares: seja, esteja, vá, dê, saiba, queira, haja.\nTras verbos de voluntad, deseo, duda, emoción + que (Quero que você venha. Espero que esteja bem. Duvido que seja verdade), y tras talvez, embora, para que, antes que.", ['Espero que le guste.', 'Quizás venga mañana.']),
 'de': ('Der Konjunktiv Präsens', "Gebildet von der 1. Person Präsens mit vertauschtem Vokal: falar → fale, fales, fale, falemos, faleis, falem; comer → coma; ter → tenha; fazer → faça; dizer → diga. Unregelmäßig: seja, esteja, vá, dê, saiba, queira, haja.\nNach Verben des Willens, Wunsches, Zweifels, Gefühls + que (Quero que você venha. Espero que esteja bem. Duvido que seja verdade) und nach talvez, embora, para que, antes que.", ['Ich hoffe, es gefällt Ihnen.', 'Vielleicht kommt er morgen.']),
 'it': ('Il congiuntivo presente', "Si forma sulla prima persona del presente scambiando la vocale: falar → fale, fales, fale, falemos, faleis, falem; comer → coma; ter → tenha; fazer → faça; dizer → diga. Irregolari: seja, esteja, vá, dê, saiba, queira, haja.\nDopo verbi di volontà, desiderio, dubbio, emozione + que (Quero que você venha. Espero que esteja bem. Duvido que seja verdade) e dopo talvez, embora, para que, antes que.", ['Spero che le piaccia.', 'Forse viene domani.']),
 'ja': ('接続法現在', "直説法現在の一人称単数から母音を入れかえて作ります：falar → fale, fales, fale, falemos, faleis, falem、comer → coma、ter → tenha、fazer → faça、dizer → diga。不規則：seja, esteja, vá, dê, saiba, queira, haja。\n意志・願望・疑い・感情 + que の後（Quero que você venha. Espero que esteja bem. Duvido que seja verdade）、また talvez, embora, para que, antes que の後で使います。", ['気に入っていただけるといいのですが。', '彼は明日来るかもしれません。']),
 'zh': ('虚拟式现在时', "由陈述式现在时第一人称单数调换元音构成：falar → fale, fales, fale, falemos, faleis, falem；comer → coma；ter → tenha；fazer → faça；dizer → diga。不规则：seja, esteja, vá, dê, saiba, queira, haja。\n用于表示意愿、希望、怀疑、情感的动词 + que 之后（Quero que você venha. Espero que esteja bem. Duvido que seja verdade），以及 talvez, embora, para que, antes que 之后。", ['希望您喜欢。', '他也许明天来。']),
 'ko': ('접속법 현재', "직설법 현재 1인칭 단수에서 모음을 바꿔 만듭니다: falar → fale, fales, fale, falemos, faleis, falem, comer → coma, ter → tenha, fazer → faça, dizer → diga. 불규칙: seja, esteja, vá, dê, saiba, queira, haja.\n의지, 바람, 의심, 감정 + que 뒤(Quero que você venha. Espero que esteja bem. Duvido que seja verdade), 그리고 talvez, embora, para que, antes que 뒤에서 씁니다.", ['마음에 드셨으면 좋겠어요.', '그는 내일 올지도 몰라요.']),
 'lt': ('Konjunktyvo esamasis laikas', "Daromas iš esamojo laiko pirmojo asmens, sukeičiant balsį: falar → fale, fales, fale, falemos, faleis, falem; comer → coma; ter → tenha; fazer → faça; dizer → diga. Netaisyklingi: seja, esteja, vá, dê, saiba, queira, haja.\nPo valios, noro, abejonės, jausmo veiksmažodžių + que (Quero que você venha. Espero que esteja bem. Duvido que seja verdade) ir po talvez, embora, para que, antes que.", ['Tikiuosi, kad jums patiks.', 'Galbūt jis ateis rytoj.']),
 'tl': ('Ang subjuntivo sa kasalukuyan', "Binubuo mula sa unang panauhan ng kasalukuyan, pinapalitan ang patinig: falar → fale, fales, fale, falemos, faleis, falem; comer → coma; ter → tenha; fazer → faça; dizer → diga. Di-regular: seja, esteja, vá, dê, saiba, queira, haja.\nPagkatapos ng pandiwa ng kagustuhan, hangarin, pag-aalinlangan, damdamin + que (Quero que você venha. Espero que esteja bem. Duvido que seja verdade), at pagkatapos ng talvez, embora, para que, antes que.", ['Sana magustuhan ninyo.', 'Baka dumating siya bukas.']),
},
'futur-subjonctif': {
 'es': ('El futuro de subjuntivo y el imperfecto', "El futuro de subjuntivo, propio del portugués, se usa tras se, quando, enquanto, logo que, quem para un hecho venidero: Quando eu chegar, ligo. Se você quiser, podemos ir. Se forma sobre la tercera persona del plural del pretérito sin -am: fizeram → fizer; foram → for; tiveram → tiver.\nImperfecto: misma base + sse (fizesse, fosse, tivesse). Hipótesis irreal: Se eu tivesse dinheiro, viajaria.", ['Si quieres, te ayudo.', 'Yo que tú, no iría.']),
 'de': ('Konjunktiv Futur und Imperfekt', "Der Konjunktiv Futur, typisch portugiesisch, steht nach se, quando, enquanto, logo que, quem für ein zukünftiges Geschehen: Quando eu chegar, ligo. Se você quiser, podemos ir. Gebildet aus der 3. Person Plural des Perfekts ohne -am: fizeram → fizer; foram → for; tiveram → tiver.\nImperfekt: gleiche Basis + sse (fizesse, fosse, tivesse). Irreale Bedingung: Se eu tivesse dinheiro, viajaria.", ['Wenn du willst, helfe ich.', 'An deiner Stelle würde ich nicht gehen.']),
 'it': ('Il congiuntivo futuro e imperfetto', "Il congiuntivo futuro, tipico del portoghese, si usa dopo se, quando, enquanto, logo que, quem per un fatto futuro: Quando eu chegar, ligo. Se você quiser, podemos ir. Si forma sulla terza persona plurale del passato senza -am: fizeram → fizer; foram → for; tiveram → tiver.\nImperfetto: stessa base + sse (fizesse, fosse, tivesse). Ipotesi irreale: Se eu tivesse dinheiro, viajaria.", ['Se vuoi, ti aiuto.', 'Al tuo posto non ci andrei.']),
 'ja': ('接続法未来と接続法過去', "接続法未来はポルトガル語特有の形で、これから起こることについて se, quando, enquanto, logo que, quem の後に使います：Quando eu chegar, ligo. Se você quiser, podemos ir。完全過去の三人称複数から -am を取って作ります：fizeram → fizer、foram → for、tiveram → tiver。\n接続法過去：同じ語幹 + sse（fizesse, fosse, tivesse）。事実に反する仮定：Se eu tivesse dinheiro, viajaria。", ['よかったら手伝うよ。', '私があなたなら行きません。']),
 'zh': ('虚拟式将来时与过去时', "虚拟式将来时是葡萄牙语特有的，用于 se, quando, enquanto, logo que, quem 之后，表示将来的事：Quando eu chegar, ligo. Se você quiser, podemos ir。由简单过去时第三人称复数去掉 -am 构成：fizeram → fizer；foram → for；tiveram → tiver。\n虚拟式过去时：同一词根 + sse（fizesse, fosse, tivesse）。非真实假设：Se eu tivesse dinheiro, viajaria。", ['如果你愿意，我来帮忙。', '如果我是你，我就不去。']),
 'ko': ('접속법 미래와 접속법 과거', "접속법 미래는 포르투갈어 특유의 형태로, 앞으로 일어날 일에 대해 se, quando, enquanto, logo que, quem 뒤에 씁니다: Quando eu chegar, ligo. Se você quiser, podemos ir. 완료 과거 3인칭 복수에서 -am을 뺀 형태입니다: fizeram → fizer, foram → for, tiveram → tiver.\n접속법 과거: 같은 어간 + sse(fizesse, fosse, tivesse). 사실과 반대되는 가정: Se eu tivesse dinheiro, viajaria.", ['원하면 도와줄게.', '내가 너라면 안 갈 거야.']),
 'lt': ('Konjunktyvo būsimasis ir būtasis', "Konjunktyvo būsimasis, būdingas portugalų kalbai, vartojamas po se, quando, enquanto, logo que, quem kalbant apie ateitį: Quando eu chegar, ligo. Se você quiser, podemos ir. Daromas iš būtojo laiko daugiskaitos trečiojo asmens be -am: fizeram → fizer; foram → for; tiveram → tiver.\nBūtasis: tas pats pagrindas + sse (fizesse, fosse, tivesse). Nereali sąlyga: Se eu tivesse dinheiro, viajaria.", ['Jei nori, padėsiu.', 'Tavo vietoje neičiau.']),
 'tl': ('Subjuntivo sa hinaharap at nakaraan', "Ang subjuntivo sa hinaharap, natatangi sa Portuges, ay ginagamit pagkatapos ng se, quando, enquanto, logo que, quem para sa darating: Quando eu chegar, ligo. Se você quiser, podemos ir. Binubuo mula sa ikatlong panauhang maramihan ng nakaraan nang walang -am: fizeram → fizer; foram → for; tiveram → tiver.\nNakaraan: parehong batayan + sse (fizesse, fosse, tivesse). Di-totoong kondisyon: Se eu tivesse dinheiro, viajaria.", ['Kung gusto mo, tutulong ako.', 'Kung ako ikaw, hindi ako pupunta.']),
},
'infinitif-personnel': {
 'es': ('El infinitivo personal y la pasiva', "El infinitivo puede llevar terminación de persona cuando tiene sujeto propio: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora (es mejor que nos vayamos ya). Para eles entenderem. Antes de saírem.\nPasiva: ser + participio concordado + por (A casa foi vendida pelo dono). Con «se»: Vende-se casa. Fala-se português.", ['Es mejor que nos vayamos.', 'El libro fue escrito por ella.']),
 'de': ('Der persönliche Infinitiv und das Passiv', "Der Infinitiv kann Personalendungen tragen, wenn er ein eigenes Subjekt hat: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora (wir gehen besser jetzt). Para eles entenderem. Antes de saírem.\nPassiv: ser + angeglichenes Partizip + por (A casa foi vendida pelo dono). Mit „se“: Vende-se casa. Fala-se português.", ['Wir gehen besser.', 'Das Buch wurde von ihr geschrieben.']),
 'it': ("L'infinito personale e il passivo", "L'infinito può avere le desinenze di persona quando ha un soggetto proprio: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora (è meglio che andiamo ora). Para eles entenderem. Antes de saírem.\nPassivo: ser + participio accordato + por (A casa foi vendida pelo dono). Con «se»: Vende-se casa. Fala-se português.", ['È meglio che ce ne andiamo.', 'Il libro è stato scritto da lei.']),
 'ja': ('人称不定詞と受動態', "不定詞は独自の主語をもつとき、人称語尾をつけることができます：falar, falares, falar, falarmos, falardes, falarem。É melhor irmos agora（今行ったほうがいい）。Para eles entenderem. Antes de saírem。\n受動態：ser + 性数一致した過去分詞 + por（A casa foi vendida pelo dono）。se を使う形：Vende-se casa. Fala-se português。", ['もう帰ったほうがいいね。', 'その本は彼女によって書かれました。']),
 'zh': ('人称不定式与被动语态', "不定式有自己的主语时，可以带人称词尾：falar, falares, falar, falarmos, falardes, falarem。É melhor irmos agora（我们最好现在走）。Para eles entenderem. Antes de saírem。\n被动语态：ser + 性数一致的过去分词 + por（A casa foi vendida pelo dono）。用 se：Vende-se casa. Fala-se português。", ['我们最好走吧。', '这本书是她写的。']),
 'ko': ('인칭 부정사와 수동태', "동사원형에 별도의 주어가 있으면 인칭 어미를 붙일 수 있습니다: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora(지금 가는 게 좋겠어요). Para eles entenderem. Antes de saírem.\n수동태: ser + 성수 일치한 과거분사 + por(A casa foi vendida pelo dono). se를 쓰는 형태: Vende-se casa. Fala-se português.", ['이제 가는 게 좋겠어요.', '그 책은 그녀가 썼어요.']),
 'lt': ('Asmeninė bendratis ir neveikiamoji rūšis', "Bendratis gali turėti asmens galūnes, kai turi savo veiksnį: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora (geriau mums dabar eiti). Para eles entenderem. Antes de saírem.\nNeveikiamoji: ser + suderintas dalyvis + por (A casa foi vendida pelo dono). Su „se“: Vende-se casa. Fala-se português.", ['Geriau mums eiti.', 'Knygą parašė ji.']),
 'tl': ('Personal na infinitive at balintiyak', "Puwedeng magkaroon ng hulaping panauhan ang infinitive kapag may sariling simuno: falar, falares, falar, falarmos, falardes, falarem. É melhor irmos agora (mas mabuting umalis na tayo). Para eles entenderem. Antes de saírem.\nBalintiyak: ser + tumutugmang participle + por (A casa foi vendida pelo dono). Gamit ang «se»: Vende-se casa. Fala-se português.", ['Mas mabuting umalis na tayo.', 'Isinulat niya ang libro.']),
},
}
